@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

@theme inline {
  --font-sans: var(--font-montserrat);
  --font-mono: var(--font-fira-code);
  --color-sidebar-ring: var(--sidebar-ring);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar: var(--sidebar);
  --color-chart-5: var(--chart-5);
  --color-chart-4: var(--chart-4);
  --color-chart-3: var(--chart-3);
  --color-chart-2: var(--chart-2);
  --color-chart-1: var(--chart-1);
  --color-ring: var(--ring);
  --color-input: var(--input);
  --color-border: var(--border);
  --color-destructive: var(--destructive);
  --color-accent-foreground: var(--accent-foreground);
  --color-accent: var(--accent);
  --color-muted-foreground: var(--muted-foreground);
  --color-muted: var(--muted);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-secondary: var(--secondary);
  --color-primary-foreground: var(--primary-foreground);
  --color-primary: var(--primary);
  --color-popover-foreground: var(--popover-foreground);
  --color-popover: var(--popover);
  --color-card-foreground: var(--card-foreground);
  --color-card: var(--card);
  --color-foreground: var(--foreground);
  --color-background: var(--background);
  --color-success: var(--success);
  --color-success-foreground: var(--success-foreground);
  --color-warning: var(--warning);
  --color-warning-foreground: var(--warning-foreground);
  --color-danger: var(--danger);
  --color-danger-foreground: var(--danger-foreground);
  --color-default: var(--default);
  --color-default-foreground: var(--default-foreground);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
  --radius-2xl: calc(var(--radius) + 8px);
  --radius-3xl: calc(var(--radius) + 12px);
  --radius-4xl: calc(var(--radius) + 16px);
}

:root {
  --radius: 0.625rem;
  --background: oklch(0.99 0.002 240);
  --foreground: oklch(0.18 0.015 250);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.18 0.015 250);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.18 0.015 250);
  --primary: oklch(0.55 0.14 250);
  --primary-foreground: oklch(0.99 0 0);
  --secondary: oklch(0.28 0.03 250);
  --secondary-foreground: oklch(0.99 0 0);
  --muted: oklch(0.96 0.005 250);
  --muted-foreground: oklch(0.52 0.02 250);
  --accent: oklch(0.6 0.15 340);
  --accent-foreground: oklch(0.99 0 0);
  --destructive: oklch(0.58 0.18 22);
  --border: oklch(0.91 0.008 250);
  --input: oklch(0.91 0.008 250);
  --ring: oklch(0.55 0.14 250 / 40%);
  --chart-1: oklch(0.58 0.14 250);
  --chart-2: oklch(0.28 0.03 250);
  --chart-3: oklch(0.6 0.15 340);
  --chart-4: oklch(0.68 0.12 70);
  --chart-5: oklch(0.58 0.14 20);
  --sidebar: oklch(0.985 0.003 250);
  --sidebar-foreground: oklch(0.18 0.015 250);
  --sidebar-primary: oklch(0.55 0.14 250);
  --sidebar-primary-foreground: oklch(0.99 0 0);
  --sidebar-accent: oklch(0.95 0.008 250);
  --sidebar-accent-foreground: oklch(0.18 0.015 250);
  --sidebar-border: oklch(0.91 0.008 250);
  --sidebar-ring: oklch(0.55 0.14 250 / 40%);
  --success: oklch(0.58 0.13 155);
  --success-foreground: oklch(0.99 0 0);
  --warning: oklch(0.74 0.13 75);
  --warning-foreground: oklch(0.99 0 0);
  --danger: oklch(0.58 0.18 22);
  --danger-foreground: oklch(0.99 0 0);
  --default: oklch(0.94 0.008 250);
  --default-foreground: oklch(0.2 0.015 250);
}

.dark {
  --background: oklch(0.14 0.012 250);
  --foreground: oklch(0.97 0.005 250);
  --card: oklch(0.18 0.015 250);
  --card-foreground: oklch(0.97 0.005 250);
  --popover: oklch(0.18 0.015 250);
  --popover-foreground: oklch(0.97 0.005 250);
  --primary: oklch(0.64 0.14 250);
  --primary-foreground: oklch(0.99 0 0);
  --secondary: oklch(0.32 0.03 250);
  --secondary-foreground: oklch(0.97 0.005 250);
  --muted: oklch(0.22 0.015 250);
  --muted-foreground: oklch(0.65 0.02 250);
  --accent: oklch(0.66 0.15 340);
  --accent-foreground: oklch(0.14 0.012 250);
  --destructive: oklch(0.62 0.16 22);
  --border: oklch(0.26 0.015 250);
  --input: oklch(0.26 0.015 250);
  --ring: oklch(0.64 0.14 250 / 40%);
  --chart-1: oklch(0.64 0.14 250);
  --chart-2: oklch(0.62 0.13 280);
  --chart-3: oklch(0.65 0.12 160);
  --chart-4: oklch(0.72 0.12 70);
  --chart-5: oklch(0.62 0.16 22);
  --sidebar: oklch(0.16 0.014 250);
  --sidebar-foreground: oklch(0.97 0.005 250);
  --sidebar-primary: oklch(0.64 0.14 250);
  --sidebar-primary-foreground: oklch(0.14 0.012 250);
  --sidebar-accent: oklch(0.22 0.015 250);
  --sidebar-accent-foreground: oklch(0.97 0.005 250);
  --sidebar-border: oklch(0.24 0.015 250);
  --sidebar-ring: oklch(0.64 0.14 250 / 40%);
  --success: oklch(0.62 0.13 155);
  --success-foreground: oklch(0.99 0 0);
  --warning: oklch(0.74 0.13 75);
  --warning-foreground: oklch(0.99 0 0);
  --danger: oklch(0.62 0.16 22);
  --danger-foreground: oklch(0.99 0 0);
  --default: oklch(0.24 0.02 250);
  --default-foreground: oklch(0.94 0.01 250);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
  }
}

@layer utilities {
  .tabs-custom {
    &[data-state="active"] {
      background-color: var(--tabs-active-bg);
      border-color: var(--tabs-active-border);
      color: var(--tabs-active-text);
    }
  }
}

@keyframes ripple {
  to {
    transform: scale(4);
    opacity: 0;
  }
}

.ripple {
  position: absolute;
  border-radius: 9999px;
  transform: scale(0);
  animation: ripple 600ms ease-out;
  background-color: currentColor;
  opacity: 0.25;
  pointer-events: none;
}

@keyframes growY {
  0%,
  100% {
    transform: scaleY(0.4);
  }
  50% {
    transform: scaleY(1);
  }
}
.animate-growY {
  animation: growY 1s ease-in-out infinite;
}

@keyframes spin-reverse {
  100% {
    transform: rotate(-360deg);
  }
}
.animate-spin-reverse {
  animation: spin-reverse 1s linear infinite;
}

@keyframes orbit {
  0% {
    transform: rotate(0deg) translateX(10px) rotate(0deg);
  }
  100% {
    transform: rotate(360deg) translateX(10px) rotate(-360deg);
  }
}
.animate-orbit {
  animation: orbit 1s linear infinite;
  transform-origin: center center;
}

@keyframes shimmer {
  100% {
    transform: translateX(100%);
  }
}
.animate-shimmer {
  animation: shimmer 1.8s infinite;
}

@keyframes progress-indeterminate {
  0% {
    transform: translateX(-100%) scaleX(0.2);
  }
  50% {
    transform: translateX(-10%) scaleX(0.8);
  }
  100% {
    transform: translateX(100%) scaleX(0.2);
  }
}
.animate-progress-indeterminate {
  animation: progress-indeterminate 1.5s infinite linear;
}

@keyframes stripe-move {
  0% {
    background-position: 0 0;
  }
  100% {
    background-position: 1rem 0;
  }
}
.animate-stripe-move {
  animation: stripe-move 1s linear infinite;
}
